  var rootSlots=materials.ToArray();partWarnings.Clear();partMaterials.Clear();script??=vehicleConfiguration;folder??=Path.GetDirectoryName(lods.Keys.First())!;shared??=settings;if(!independent&&JointFrameRequested||script==null)return;VehiclePart[] parts;try{parts=VehicleParts.Read(script,!independent&&CabinFrameRequested);}catch(Exception ex){partWarnings.Add(ex.Message);return;}
  foreach(var part in parts)try{
   string path=VehicleAssets.Resolve(part.Model,folder,MediaFolder());var model=AssetModel(path);
   string prefix="__part_"+Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(path+"|"+part.Material)))[..12]+"__";int first=materials.Count;materials.AddRange(model.Materials.Select(m=>prefix+m));Dictionary<string,MaterialSettings> maps;
   if(part.Material!=null){string material=VehicleAssets.Resolve(part.Material,folder,MediaFolder());maps=MaterialDocuments.ResourceMaps(model,material);}else maps=model.Materials.Select((m,i)=>(Name:m,Value:shared.GetValueOrDefault(m)??(i<rootSlots.Length?shared.GetValueOrDefault(rootSlots[i]):null)??new MaterialSettings())).ToDictionary(p=>p.Name,p=>p.Value);if(!partMaterials.Any(m=>m.Prefix==prefix))partMaterials.Add((prefix,maps));
   if(!Matrix4x4.Invert(part.Transform,out var inverse))throw new InvalidDataException("Invalid attachment transform");var normalMatrix=Matrix4x4.Transpose(inverse);
   foreach(var node in model.Nodes){var p=new float[node.Positions.Length];var n=new float[node.Normals.Length];for(int i=0;i<node.VertexCount;i++){var v=Vector3.Transform(new(node.Positions[i*3],node.Positions[i*3+1],node.Positions[i*3+2]),part.Transform);var normal=Vector3.Normalize(Vector3.TransformNormal(new(node.Normals[i*3],node.Normals[i*3+1],node.Normals[i*3+2]),normalMatrix));p[i*3]=v.X;p[i*3+1]=v.Y;p[i*3+2]=v.Z;n[i*3]=normal.X;n[i*3+1]=normal.Y;n[i*3+2]=normal.Z;}entries.Add(new{Name=prefix+node.Name,Positions=p,Normals=n,node.Uv,Indices=node.Indices.Select(i=>(int)i).ToArray(),Groups=node.Groups.Select(g=>g with{Material=g.Material+first}).ToArray(),Cargo=false,Part=true});}
  }catch(Exception ex){partWarnings.Add(part.Id+": "+ex.Message);}
